// @ohos/dsh-ptc-runtime-vm — worker entry.
//
// Runs INSIDE a worker_thread of the dsh process. Receives one run spec over
// parentPort, evaluates the model's program inside a fresh `node:vm` context
// whose globals are ONLY what this runtime provides (console, the binding
// namespaces such as `tools`, their error classes) plus the ECMAScript
// intrinsics — no `require`, no `process`, no Node APIs. Binding calls travel
// back to the main thread as messages; the main thread enforces the
// elapsed-time budget and kills this worker with `terminate()` when it fires
// (that also breaks synchronous infinite loops, which a bare vm timeout on an
// async body cannot).
//
// Protocol (worker → main): {t:'log', level, text} | {t:'call', id, ns, name, args}
//                           | {t:'done', ok, value?, error?{kind, message}}
// Protocol (main → worker): {t:'run', program, namespaces} | {t:'result', id, settle}
//
// Deliberately self-contained: no imports beyond node:worker_threads/node:vm,
// and a local copy of the lossless-JSON validator, so a worker can never
// re-enter plugin resolution that may not be available from its location.

import { parentPort } from "node:worker_threads";
import vm from "node:vm";

const MAX_PENDING_CALLS = 64;

/** Lossless-JSON check shared with index.js (duplicated on purpose — see header). */
function jsonViolation(value, label) {
	if (value === null) return null;
	const kind = typeof value;
	if (kind === "boolean") return null;
	if (kind === "number") {
		if (!Number.isFinite(value)) return `${label}: non-finite number`;
		return null;
	}
	if (kind === "string") return null;
	if (kind === "object") {
		if (Array.isArray(value)) {
			for (let index = 0; index < value.length; index += 1) {
				const violation = jsonViolation(value[index], `${label}[${index}]`);
				if (violation !== null) return violation;
			}
			return null;
		}
		for (const key of Object.keys(value)) {
			const violation = jsonViolation(value[key], `${label}.${key}`);
			if (violation !== null) return violation;
		}
		return null;
	}
	return `${label}: ${kind} is not a JSON value`;
}

function messageOf(error) {
	if (error instanceof Error) return error.message;
	if (error !== null && typeof error === "object" && typeof error.message === "string") return error.message;
	return String(error);
}

/**
 * Context setup, executed INSIDE the fresh vm context. Fully data-driven —
 * every namespace/error-class name is read from `__ptc_defs` at runtime and
 * was validated by the main thread before posting, so nothing from the spec
 * is ever interpolated into source text.
 */
const SETUP = `
"use strict";
const hooks = globalThis.__ptc_hooks;
const defs = globalThis.__ptc_defs;
delete globalThis.__ptc_hooks;
delete globalThis.__ptc_defs;

function formatPart(part) {
	if (typeof part === "string") return part;
	try {
		const text = JSON.stringify(part);
		if (typeof text === "string") return text;
	} catch {}
	return String(part);
}
globalThis.console = {
	log: (...parts) => hooks.hostLog("log", parts.map(formatPart).join(" ")),
	info: (...parts) => hooks.hostLog("info", parts.map(formatPart).join(" ")),
	warn: (...parts) => hooks.hostLog("warn", parts.map(formatPart).join(" ")),
	error: (...parts) => hooks.hostLog("error", parts.map(formatPart).join(" ")),
	debug: (...parts) => hooks.hostLog("debug", parts.map(formatPart).join(" "))
};

const errorClasses = new Map();
for (const def of defs) {
	if (def.errorClass !== null) {
		const spec = def.errorClass;
		const Cls = class extends Error {
			constructor(message, memberValue) {
				super(message);
				this.name = spec.name;
				this[spec.memberNameProperty] = memberValue;
			}
		};
		errorClasses.set(def.global, Cls);
		globalThis[spec.name] = Cls;
	}
}

let inFlight = 0;
for (const def of defs) {
	const namespace = Object.create(null);
	for (const name of def.names) {
		Object.defineProperty(namespace, name, {
			enumerable: true,
			writable: false,
			configurable: false,
			value: async function (args) {
				if (inFlight >= ${MAX_PENDING_CALLS}) {
					throw new Error("too many concurrent binding calls in flight (" + ${MAX_PENDING_CALLS} + ")");
				}
				inFlight += 1;
				try {
					const settled = await hooks.hostCall(def.global, name, args === undefined ? {} : args);
					if (settled.isError) {
						const Cls = errorClasses.get(def.global);
						if (Cls !== undefined) throw new Cls(settled.message, name);
						throw new Error(settled.message);
					}
					return settled.value;
				} finally {
					inFlight -= 1;
				}
			}
		});
	}
	Object.defineProperty(globalThis, def.global, {
		value: namespace,
		writable: false,
		configurable: false,
		enumerable: true
	});
}
`;

let nextCallId = 1;
const pendingCalls = new Map();

function post(message) {
	parentPort.postMessage(message);
}

async function executeRun(spec) {
	if (typeof spec.program !== "string") throw new Error("run spec: program must be a string");
	if (!Array.isArray(spec.namespaces)) throw new Error("run spec: namespaces must be an array");

	const sandbox = {};
	const context = vm.createContext(sandbox, { name: "ptc-vm" });
	sandbox.__ptc_hooks = {
		hostLog: (level, text) => post({ t: "log", level, text }),
		hostCall: (ns, name, args) => {
			const violation = jsonViolation(args, `tools.${name} args`);
			if (violation !== null) return Promise.reject(new Error(violation));
			const id = nextCallId;
			nextCallId += 1;
			return new Promise((resolve, reject) => {
				pendingCalls.set(id, { resolve, reject });
				post({ t: "call", id, ns, name, args });
			});
		}
	};
	sandbox.__ptc_defs = spec.namespaces;

	vm.runInContext(SETUP, context, { filename: "ptc-setup.js" });
	const completion = vm.runInContext(`(async () => {\n${spec.program}\n})()`, context, {
		filename: "ptc-program.js"
	});
	const value = await completion;
	if (value !== undefined) {
		const violation = jsonViolation(value, "program result");
		if (violation !== null) {
			post({ t: "done", ok: false, error: { kind: "invalid-output", message: `${violation} — return lossless JSON, or console.log a rendering instead` } });
			return;
		}
	}
	post({ t: "done", ok: true, ...(value === undefined ? {} : { value }) });
}

parentPort.on("message", (message) => {
	if (message === null || typeof message !== "object") return;
	if (message.t === "run") {
		executeRun(message).catch((error) => {
			post({ t: "done", ok: false, error: { kind: "exception", message: messageOf(error) } });
		});
		return;
	}
	if (message.t === "result") {
		const pending = pendingCalls.get(message.id);
		if (pending === undefined) return;
		pendingCalls.delete(message.id);
		// The settle object crosses untouched; the in-context proxy unwraps it
		// so a rejected member call materializes as the declared error class
		// (e.g. ToolCallError) inside the program's own realm.
		pending.resolve(message.settle);
	}
});

process.on("unhandledRejection", (reason) => {
	post({ t: "log", level: "error", text: `unhandled rejection: ${messageOf(reason)}` });
});
